  return condition();
}

coding.solution:
async function waitUntil(condition, { timeout = 1000, interval = 50, message = 'condition' } = {}) {
  const deadline = Date.now() + timeout;
  for (;;) {
    try {
      const v = await condition();
      if (v) return v;
    } catch (e) {
      // ignore while polling, like FluentWait.ignoring(...)
    }
    if (Date.now() >= deadline) throw new Error(`Timed out after ${timeout}ms waiting for ${message}`);
    await new Promise(r => setTimeout(r, interval));
  }
}

