  return read();
}

coding.solution:
async function waitForChange(read, before, { timeout = 1000, interval = 20 } = {}) {
  const deadline = Date.now() + timeout;
  for (;;) {
    const v = await read();
    if (v !== before && v !== '' && v !== null && v !== undefined) return v;
    if (Date.now() >= deadline) throw new Error('value did not change from ' + JSON.stringify(before));
    await new Promise(r => setTimeout(r, interval));
  }
}

def schedule(timeout, first=0.1, factor=2.0, max_interval=1.0):
    times = [0]
    t, gap = 0.0, first
    while True:
        nxt = t + min(gap, max_interval)
        if nxt >= timeout - 1e-9:
            break
        t = nxt
        times.append(round(t, 3))
        gap *= factor
    if times[-1] < timeout:
        times.append(round(timeout, 3))
    return times
